import rs.unicredit.cbr.model.CbrTransactionStat;
import rs.unicredit.cbr.mq.MqMessageService;
import rs.unicredit.cbr.repository.CbrStageSnapshotRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;
import rs.unicredit.cbr.repository.CbrTransactionRequestRepository;

@Service
@RequiredArgsConstructor
public class StageRestoreService {

    private static final Logger LOG = LoggerFactory.getLogger(StageRestoreService.class);
    private static final String CREATED_BY = "MANUAL_STAGE_RESTORE";
    private static final String ERROR_STAGE = "S11";
    private static final Set<String> VALIDATION_FLOW_STAGES = Set.of("S6", "S7", "S7A", "S7B", "S7C", "S12");
    private static final Set<String> EARLY_STAGES = Set.of("S1", "S2", "S3", "S4", "S5");

    private final CbrStageSnapshotRepository stageSnapshotRepository;
    private final CbrTransactionRequestRepository requestRepository;
    private final CbrTransactionRepository transactionRepository;
    private final StageTransitionService stageTransitionService;
    private final MessageOrchestrationService messageOrchestrationService;
    private final CbrTransactionResponseService responseService;
    private final ObjectProvider<MqMessageService> mqMessageServiceProvider;
    private final ObjectMapper objectMapper;

    @Transactional
    public StageRestoreResponse restoreFromSnapshot(StageRestoreRequest request) {
        if (request == null || request.getRequestId() == null) {
            throw new IllegalArgumentException("requestId is required");
        }
        String targetStageCode = normalize(request.getStageCode());
        if (isBlank(targetStageCode)) {
            throw new IllegalArgumentException("stageCode is required");
        }

        Long requestId = request.getRequestId();
        CbrTransactionRequest txnRequest = requestRepository.findById(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
        CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Transaction not found for requestId=" + requestId));
        CbrStageSnapshot snapshot = stageSnapshotRepository
                .findFirstByRequestIdAndToStageCodeOrderByIdDesc(requestId, targetStageCode)
                .orElseThrow(() -> new IllegalArgumentException(
                        "Snapshot not found for requestId=" + requestId + " and stageCode=" + targetStageCode));

        SnapshotPayload payload = parseSnapshot(snapshot.getSnapshotJson());
        applyTransactionRestore(txn, payload);
        transactionRepository.save(txn);

        String fromStageCode = normalize(txn.getStatus());
        String note = isBlank(request.getNote())
                ? "Manual restore from snapshot to " + targetStageCode
                : request.getNote();
        stageTransitionService.transition(txnRequest, txn, targetStageCode, note, CREATED_BY);

        List<String> executedActions = new ArrayList<>();
        List<String> failedActions = new ArrayList<>();
        if (request.isExecutePostActions() && request.getPostActions() != null) {
            for (String action : request.getPostActions()) {
                if (isBlank(action)) {
                    continue;
                }
                try {
                    executePostAction(requestId, action);
                    executedActions.add(normalize(action));
                } catch (Exception ex) {
                    String actionCode = normalize(action);
                    LOG.warn("Post action {} failed for requestId={}: {}", actionCode, requestId, ex.getMessage());
                    failedActions.add(actionCode + ": " + ex.getMessage());
                }
            }
        }

        String message = failedActions.isEmpty()
                ? "Snapshot restored to " + targetStageCode
                : "Snapshot restored to " + targetStageCode + ", but some post actions failed: "
                        + String.join(" | ", failedActions);
        return StageRestoreResponse.builder()
                .requestId(requestId)
                .fromStageCode(fromStageCode)
                .restoredStageCode(targetStageCode)
                .snapshotId(snapshot.getId())
                .postActionsExecuted(!executedActions.isEmpty())
                .executedActions(executedActions)
                .message(message)
                .build();
    }

    @Transactional
    public StageRestoreResponse restoreFromLastNonErrorStage(Long requestId, String note, boolean executePostActions) {
        if (requestId == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "requestId is required");
        }

        CbrTransactionRequest txnRequest = requestRepository.findById(requestId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Request not found: " + requestId));

        CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.UNPROCESSABLE_ENTITY,
                        "No transaction found for requestId=" + requestId + ". Replay/re-ingest is required."));

        String currentStage = normalize(txn.getStatus());
        if (isBlank(currentStage) && txnRequest != null) {
            currentStage = normalize(txnRequest.getStatus());
        }
        if (!ERROR_STAGE.equalsIgnoreCase(currentStage)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Request is not in S11");
        }

        CbrStageSnapshot snapshot = stageSnapshotRepository
                .findFirstByRequestIdAndToStageCodeNotOrderByIdDesc(requestId, ERROR_STAGE)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.CONFLICT,
                        "No non-S11 snapshot found for requestId=" + requestId));

        String targetStageCode = normalize(snapshot.getToStageCode());
        List<String> postActions = resolvePostActions(targetStageCode);
        LOG.info(
                "Restore-from-error resolved requestId={} currentStage={} targetStage={} executePostActions={} postActions={}",
                requestId,
                currentStage,
                targetStageCode,
                executePostActions,
                postActions);
        String resolvedNote = isBlank(note)
                ? "Auto-restore from S11 to " + targetStageCode + " (Last Non-S11)"
                : note;

        StageRestoreRequest restoreRequest = StageRestoreRequest.builder()
                .requestId(requestId)
                .stageCode(targetStageCode)
                .executePostActions(executePostActions)
                .postActions(postActions)
                .note(resolvedNote)
                .build();

        return restoreFromSnapshot(restoreRequest);
    }

    @Transactional
    public StageRestoreResponse restoreFromLastNonErrorStageByTransactionId(
            Long transactionId,
            Long fallbackRequestId,
            String note,
            boolean executePostActions) {
        if (transactionId == null && fallbackRequestId == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "id is required");
        }

        if (transactionId != null) {
            CbrTransaction txn = transactionRepository.findWithRegulatoryDetailsById(transactionId)
                    .orElseThrow(() -> new ResponseStatusException(
                            HttpStatus.UNPROCESSABLE_ENTITY,
                            "No transaction found for id=" + transactionId + ". Replay/re-ingest is required."));

            Long requestId = txn.getRequest() != null ? txn.getRequest().getId() : null;
            if (requestId == null) {
                throw new ResponseStatusException(
                        HttpStatus.UNPROCESSABLE_ENTITY,
                        "No requestId linked to transaction id=" + transactionId + ". Replay/re-ingest is required.");
            }

            return restoreFromLastNonErrorStage(requestId, note, executePostActions);
        }

        return restoreFromLastNonErrorStage(fallbackRequestId, note, executePostActions);
    }

    private SnapshotPayload parseSnapshot(String snapshotJson) {
        if (isBlank(snapshotJson)) {
            throw new IllegalStateException("Snapshot JSON is empty");
        }
        try {
            JsonNode root = objectMapper.readTree(snapshotJson);
            JsonNode txnNode = root.get("transaction");
            if (txnNode == null || txnNode.isNull()) {
                throw new IllegalStateException("Snapshot JSON does not contain transaction");
            }
            CbrTransaction snapshotTransaction = objectMapper.treeToValue(txnNode, CbrTransaction.class);
            List<CbrTransactionStat> snapshotStats = new ArrayList<>();
            JsonNode statsNode = root.get("regulatoryDetails");
            if (statsNode != null && statsNode.isArray()) {
                for (JsonNode node : statsNode) {
                    snapshotStats.add(objectMapper.treeToValue(node, CbrTransactionStat.class));
                }
            }
            return new SnapshotPayload(snapshotTransaction, snapshotStats);
        } catch (JsonProcessingException ex) {
            throw new IllegalStateException("Failed to parse snapshot JSON", ex);
        }
    }

    private void applyTransactionRestore(CbrTransaction target, SnapshotPayload payload) {
        CbrTransaction source = payload.transaction();
        BeanUtils.copyProperties(
                source,
                target,
                "id",
                "request",
                "regulatoryDetails",
                "status",
                "createdAt",
                "updatedAt");

        target.getRegulatoryDetails().clear();
        for (CbrTransactionStat snapshotStat : payload.regulatoryDetails()) {
            CbrTransactionStat stat = CbrTransactionStat.builder()
                    .transaction(target)
                    .splitStatCode(snapshotStat.getSplitStatCode())
                    .splitAmount(snapshotStat.getSplitAmount())
                    .splitAmountCurrency(snapshotStat.getSplitAmountCurrency())
                    .invoiceNumber(snapshotStat.getInvoiceNumber())
                    .invoiceYear(snapshotStat.getInvoiceYear())
                    .build();
            target.getRegulatoryDetails().add(stat);
        }
    }

    private void executePostAction(Long requestId, String action) {
        String code = normalize(action).toUpperCase(Locale.ROOT);
        LOG.info("Executing restore post action requestId={} action={}", requestId, code);
        switch (code) {
            case "ORCHESTRATE_AFTER_INGESTION" ->
                messageOrchestrationService.orchestrateAfterIngestion(requestId);
            case "START_VALIDATION_FLOW" ->
                messageOrchestrationService.startValidationFlow(requestId, "Manual restore post action");
            case "PREPARE_RESPONSE" -> responseService.prepareResponse(requestId);
            case "SEND_TO_DESTINATION" -> sendToDestination(requestId);
            case "SEND_TO_OM" -> sendToOm(requestId);
            case "SEND_TO_GSE" -> sendToGse(requestId);
            default -> throw new IllegalArgumentException("Unsupported post action: " + action);
        }
        LOG.info("Finished restore post action requestId={} action={}", requestId, code);
    }

    private List<String> resolvePostActions(String targetStageCode) {
        String normalizedStage = normalize(targetStageCode);
        if (isBlank(normalizedStage)) {
            return List.of();
        }

        if ("S2".equalsIgnoreCase(normalizedStage)) {
            return List.of("ORCHESTRATE_AFTER_INGESTION");
        }
        if ("S9".equalsIgnoreCase(normalizedStage)) {
            return List.of("SEND_TO_DESTINATION");
        }
        if ("S10".equalsIgnoreCase(normalizedStage)) {
            return List.of();
        }
        if (VALIDATION_FLOW_STAGES.contains(normalizedStage.toUpperCase(Locale.ROOT))
                || EARLY_STAGES.contains(normalizedStage.toUpperCase(Locale.ROOT))) {
            return List.of("START_VALIDATION_FLOW");
        }
        return List.of();
    }

    private void sendToDestination(Long requestId) {
        CbrTransactionResponse response = responseService.prepareResponse(requestId);
        String destination = normalize(response != null ? response.getDestinationSystem() : null);
        if ("OM".equalsIgnoreCase(destination)) {
            sendToOm(requestId);
            return;
        }
        if ("GSE".equalsIgnoreCase(destination)) {
            sendToGse(requestId);
            return;
        }
        throw new IllegalStateException("Unsupported destination system: " + destination);
    }

    private void sendToOm(Long requestId) {
        MqMessageService service = mqMessageServiceProvider.getIfAvailable();
        if (service == null) {
            throw new IllegalStateException("MQ message service is not available");
        }
        service.sendCbrRequestToOm(requestId);
    }

    private void sendToGse(Long requestId) {
        MqMessageService service = mqMessageServiceProvider.getIfAvailable();
        if (service == null) {
            throw new IllegalStateException("MQ message service is not available");
        }
        service.sendCbrRequestToGse(requestId);
    }

    private String normalize(String value) {
        return value == null ? null : value.trim();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private record SnapshotPayload(CbrTransaction transaction, List<CbrTransactionStat> regulatoryDetails) {
    }
