    @Transactional(readOnly = true)
    public CbrTransactionDTO getByTransactionId(Long transactionId) {
        CbrTransaction transaction = cbrTransactionRepository.findWithRegulatoryDetailsById(transactionId)
                .filter(this::isOutgoingDirection)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Outgoing transaction not found for id=" + transactionId));

        return transactionDtoMapper.toDto(transaction, cbrStageService.getStageShortNamesByCode());
    }

    @Override
    @Transactional(readOnly = true)
    public List<CbrTransactionDTO> getForEntry() {
        List<String> statusCodes = cbrStageService.getActiveStageCodesByOrders(
                STAGE_ORDERS_FOR_ENTRY);
        if (statusCodes.isEmpty()) {
            return List.of();
        }
        return mapToDto(transactionRepository.findAllByDirectionInAndStatusIn(
                OUTGOING_DIRECTIONS,
                statusCodes));
    }

    @Override
    @Transactional(readOnly = true)
    public List<CbrTransactionDTO> getForRework() {
        List<String> statusCodes = cbrStageService.getActiveStageCodesByOrders(
                STAGE_ORDERS_FOR_REWORK);
        if (statusCodes.isEmpty()) {
            return List.of();
        }
        return mapToDto(transactionRepository.findAllByDirectionInAndStatusIn(
