    @Override
    @Transactional(readOnly = true)
    public List<CbrTransactionDTO> getErrors() {
        List<CbrTransactionDTO> errors = new ArrayList<>(mapToDto(
                transactionRepository.findAllByDirectionInAndStatusIn(
                        OUTGOING_DIRECTIONS,
