    @Override
    @Transactional(readOnly = true)
    public List<CbrTransactionDTO> getMyOrdersForRework() {
        List<String> statusCodes = cbrStageService.getActiveStageCodesByOrders(
                STAGE_ORDERS_FOR_REWORK);
        if (statusCodes.isEmpty()) {
            return List.of();
        }

        return mapToDto(transactionRepository
                .findAllByDirectionInAndStatusInAndOrderSubmittedByIgnoreCase(
                        OUTGOING_DIRECTIONS,
                        statusCodes,
                        currentUserService.getUsername()));
    }

    @Override
    @Transactional(readOnly = true)
    public List<ActionLogDto> getActionLog(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        return actionLogService.getAllByRequestId(resolveRequestId(transaction));
    }

    @Override
    @Transactional(readOnly = true)
    public ManualValidationErrorsResponse getManualValidationErrors(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        Long requestId = transaction.getRequest() != null ? transaction.getRequest().getId() : null;

        return manualValidationErrorsService.getByRequestId(requestId)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Manual validation errors not found for transaction id=" + transactionId));
    }

    @Override
    @Transactional
    public CbrTransactionDTO updateManualEntryDetails(
            Long transactionId,
            ManualEntryDetailsUpdateRequest request) {
        if (request == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Request body is required.");
        }

        CbrTransaction transaction = cbrTransactionRepository.findWithRegulatoryDetailsById(transactionId)
                .filter(this::isOutgoingDirection)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Outgoing transaction not found for id=" + transactionId));

        Map<String, Object> beforeSnapshot = snapshotEditableFields(transaction);
        applyManualEntryDetails(transaction, request);
        Map<String, Object> afterSnapshot = snapshotEditableFields(transaction);
        Map<String, Object> changes = calculateChanges(beforeSnapshot, afterSnapshot);

        if (!changes.isEmpty()) {
            transaction.setOrderSubmittedBy(resolveCurrentUsername());
            cbrTransactionRepository.save(transaction);
        }

        actionLogService.logAction(
                resolveRequestId(transaction),
                ACTION_MANUAL_ENTRY_UPDATE,
                changes);

        return transactionDtoMapper.toDto(transaction, cbrStageService.getStageShortNamesByCode());
    }

    @Override
    @Transactional
    public void returnForCorrection(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        String currentStatus = normalizeText(transaction.getStatus());
        if (currentStatus == null
                || !RETURN_FOR_CORRECTION_ALLOWED_SOURCE_STATUSES.contains(currentStatus.toUpperCase())) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Action 'Vrati na doradu' is allowed only for outgoing transactions in status S7A, S7B or S7C.");
        }
        String currentUsername = resolveCurrentUsername();
        markOrderSubmittedBy(transaction, currentUsername);

        stageTransitionService.transition(
                transaction.getRequest(),
                transaction,
                STATUS_S12,
                "VRATI_NA_DORADU",
                currentUsername);

        logOutgoingAction(
                resolveRequestId(transaction),
                currentStatus,
                STATUS_S12,
                ACTION_RETURN_FOR_CORRECTION);
    }

    @Override
    @Transactional
    public void forceProcessing(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        String currentStatus = normalizeText(transaction.getStatus());
        if (currentStatus == null || !STATUS_S4.equalsIgnoreCase(currentStatus)) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Action 'Posalji na rucni unos' is allowed only for outgoing transactions in status S4.");
        }
        String currentUsername = resolveCurrentUsername();
        markOrderSubmittedBy(transaction, currentUsername);

        stageTransitionService.transition(
                transaction.getRequest(),
                transaction,
                STATUS_S7,
                "POSALJI_NA_RUCNI_UNOS",
                currentUsername);

        logOutgoingAction(
                resolveRequestId(transaction),
                currentStatus,
                STATUS_S7,
                ACTION_FORCE_PROCESSING);
    }

    @Override
    @Transactional
    public void sendForVerificationEdit(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        String currentStatus = normalizeText(transaction.getStatus());
        if (currentStatus == null
                || !SEND_FOR_VERIFICATION_ALLOWED_SOURCE_STATUSES.contains(currentStatus.toUpperCase())) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Action 'Posalji na verifikaciju' is allowed only for outgoing transactions in status S7 or S12.");
        }

        Long requestId = transaction.getRequest() != null ? transaction.getRequest().getId() : null;
        List<ValidationApplyResult> validationResults = validationEvaluationService
                .evaluateAllByRequestIdWithoutStageTransition(requestId)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Validation check-all result not found for request_id=" + requestId));

        List<String> validationFailures = collectValidationFailures(validationResults);
        if (!validationFailures.isEmpty()) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    VALIDATION_FAILED_PREFIX + String.join(VALIDATION_FAILED_SEPARATOR, validationFailures));
        }
        String currentUsername = resolveCurrentUsername();
        markOrderSubmittedBy(transaction, currentUsername);

        stageTransitionService.transition(
                transaction.getRequest(),
                transaction,
                STATUS_S7A,
                "POSALJI_NA_VERIFIKACIJU",
                currentUsername);

        logOutgoingAction(
                resolveRequestId(transaction),
                currentStatus,
                STATUS_S7A,
                ACTION_SEND_FOR_VERIFICATION);
    }

    @Override
    @Transactional
    public void sendForVerificationReject(Long transactionId, VerificationRejectRequest request) {
        if (request == null || isBlank(request.getRejectCode())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "rejectCode is required.");
        }

        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        String currentStatus = normalizeText(transaction.getStatus());
        if (currentStatus == null
                || !SEND_FOR_VERIFICATION_ALLOWED_SOURCE_STATUSES.contains(currentStatus.toUpperCase())) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Action 'Odbijanje transakcije' is allowed only for outgoing transactions in status S7 or S12.");
        }

        String rejectCode = normalizeText(request.getRejectCode());
        CbrReject reject = cbrRejectService.findActiveByCode(rejectCode)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.BAD_REQUEST,
                        "Reject code is not valid or not active: " + rejectCode));
        String previousRejectCode = normalizeText(transaction.getRejectCode());
        String previousRejectReason = normalizeText(transaction.getRejectReason());
        String rejectReason = normalizeText(reject.getRejectName());
        if (isBlank(rejectReason)) {
            rejectReason = normalizeText(request.getRejectReason());
        }
        String currentUsername = resolveCurrentUsername();

        transaction.setRejectCode(rejectCode);
        transaction.setRejectReason(rejectReason);
        markOrderSubmittedBy(transaction, currentUsername);
        cbrTransactionRepository.save(transaction);

        stageTransitionService.transition(
                transaction.getRequest(),
                transaction,
                STATUS_S7B,
                "ODBIJANJE_TRANSAKCIJE",
                currentUsername);

        String currentStatusValue = currentStatus == null || currentStatus.isBlank()
                ? UNKNOWN_STATUS
                : currentStatus;
        LinkedHashMap<String, Object> changes = new LinkedHashMap<>();
        changes.put("status_from", currentStatusValue);
        changes.put("status_to", STATUS_S7B);
        if (!Objects.equals(previousRejectCode, rejectCode)) {
            changes.put("reject_code_from", previousRejectCode);
            changes.put("reject_code_to", rejectCode);
        }
        if (!Objects.equals(previousRejectReason, rejectReason)) {
            changes.put("reject_reason_from", previousRejectReason);
            changes.put("reject_reason_to", rejectReason);
        }
        actionLogService.logAction(resolveRequestId(transaction), ACTION_SEND_FOR_VERIFICATION_REJECT, changes);
    }

    @Override
    @Transactional
    public void sendForVerificationForce(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        String currentStatus = normalizeText(transaction.getStatus());
        if (currentStatus == null
                || !SEND_FOR_VERIFICATION_ALLOWED_SOURCE_STATUSES.contains(currentStatus.toUpperCase())) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Action 'Forsiraj' is allowed only for outgoing transactions in status S7 or S12.");
        }
        String currentUsername = resolveCurrentUsername();
        markOrderSubmittedBy(transaction, currentUsername);

        stageTransitionService.transition(
                transaction.getRequest(),
                transaction,
                STATUS_S7C,
                "FORSIRAJ",
                currentUsername);

        logOutgoingAction(
                resolveRequestId(transaction),
                currentStatus,
                STATUS_S7C,
                ACTION_SEND_FOR_VERIFICATION_FORCE);
    }

    @Override
    @Transactional
    public void approveVerification(Long transactionId) {
        CbrTransaction transaction = findOutgoingTransaction(transactionId);
        String currentStatus = normalizeText(transaction.getStatus());
        if (currentStatus == null
                || !APPROVE_VERIFICATION_ALLOWED_SOURCE_STATUSES.contains(currentStatus.toUpperCase())) {
            throw new ResponseStatusException(
                    HttpStatus.CONFLICT,
                    "Action 'Odobreno' is allowed only for outgoing transactions in status S7A, S7B or S7C.");
        }

        String currentUsername = resolveCurrentUsername();
        String orderSubmittedBy = normalizeText(transaction.getOrderSubmittedBy());
        if (ENABLE_SELF_VERIFICATION_BLOCK
                && !isBlank(currentUsername)
                && !isBlank(orderSubmittedBy)
                && orderSubmittedBy.equalsIgnoreCase(currentUsername)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, SELF_VERIFICATION_NOT_ALLOWED_CODE);
        }

        Long requestId = transaction.getRequest() != null ? transaction.getRequest().getId() : null;
        messageOrchestrationService.prepareAndSendToDestination(requestId);
        cbrTransactionRepository.updateOrderVerifiedBy(transactionId, currentUsername);

        logOutgoingAction(
                resolveRequestId(transaction),
                currentStatus,
                STATUS_S10,
                ACTION_APPROVE_VERIFICATION);
    }

    private CbrTransaction findOutgoingTransaction(Long transactionId) {
        return transactionRepository.findById(transactionId)
                .filter(this::isOutgoingDirection)
                .orElseThrow(() -> new ResponseStatusException(
                        HttpStatus.NOT_FOUND,
                        "Outgoing transaction not found for id=" + transactionId));
    }

    private boolean isOutgoingDirection(CbrTransaction transaction) {
        if (transaction == null || transaction.getDirection() == null) {
            return false;
        }
        return OUTGOING_DIRECTIONS.contains(transaction.getDirection());
    }

    private void logOutgoingAction(
            String requestId,
            String currentStatus,
            String targetState,
            String actionCode) {
        String currentStatusValue = currentStatus == null || currentStatus.isBlank()
                ? UNKNOWN_STATUS
                : currentStatus;

        LinkedHashMap<String, Object> changes = new LinkedHashMap<>();
        changes.put("status_from", currentStatusValue);
        changes.put("status_to", targetState);

        actionLogService.logAction(requestId, actionCode, changes);
    }

    private String resolveRequestId(CbrTransaction transaction) {
        if (transaction != null
                && transaction.getRequest() != null
                && transaction.getRequest().getId() != null) {
            return String.valueOf(transaction.getRequest().getId());
        }
        throw new IllegalStateException(
                "Request ID is missing for transaction id="
                        + (transaction != null ? transaction.getId() : null));
    }

    private void applyManualEntryDetails(
            CbrTransaction transaction,
            ManualEntryDetailsUpdateRequest request) {
        transaction.setReportType(normalizeText(request.getReportType()));
        transaction.setCustomerId(normalizeText(request.getCustomerId()));
        transaction.setPaymentInstrument(normalizeText(request.getPaymentInstrument()));
        transaction.setSpecialMark(normalizeText(request.getSpecialMark()));
        transaction.setCountryCode1(normalizeText(request.getCountryCode1()));
        transaction.setCountryCode2(normalizeText(request.getCountryCode2()));
        transaction.setLoanNumber(normalizeText(request.getLoanNumber()));
        transaction.setLoanYear(normalizeText(request.getLoanYear()));
        transaction.setCustomerStp(normalizeText(request.getCustomerStp()));
        transaction.setDrStatisticalCode(normalizeText(request.getDrStatisticalCode()));
        transaction.setCrStatisticalCode(normalizeText(request.getCrStatisticalCode()));

        applyRegulatoryDetails(transaction, request.getRegulatoryDetails());
    }

    private void applyRegulatoryDetails(
            CbrTransaction transaction,
            List<ManualEntryDetailsUpdateRequest.RegulatoryDetailItem> requestedDetails) {
        if (requestedDetails == null) {
            return;
        }

        Map<Long, CbrTransactionStat> existingById = transaction.getRegulatoryDetails().stream()
                .filter(detail -> detail.getId() != null)
                .collect(java.util.stream.Collectors.toMap(
                        CbrTransactionStat::getId,
                        detail -> detail));

        List<CbrTransactionStat> updatedDetails = new java.util.ArrayList<>();
        for (ManualEntryDetailsUpdateRequest.RegulatoryDetailItem detailRequest : requestedDetails) {
            if (detailRequest == null || isEmptyRegulatoryDetail(detailRequest)) {
                continue;
            }

            CbrTransactionStat detail = null;
            if (detailRequest.getId() != null) {
                detail = existingById.get(detailRequest.getId());
            }

            if (detail == null) {
                detail = new CbrTransactionStat();
                detail.setTransaction(transaction);
            }

            detail.setSplitStatCode(normalizeText(detailRequest.getSplitStatCode()));
            detail.setSplitAmount(parseBigDecimal(detailRequest.getSplitAmount(), "splitAmount"));
            detail.setInvoiceNumber(normalizeText(detailRequest.getInvoiceNumber()));
            detail.setInvoiceYear(normalizeText(detailRequest.getInvoiceYear()));
            detail.setSplitAmountCurrency(normalizeText(detailRequest.getSplitAmountCurrency()));

            updatedDetails.add(detail);
        }

        transaction.getRegulatoryDetails().clear();
        transaction.getRegulatoryDetails().addAll(updatedDetails);
    }

    private Map<String, Object> snapshotEditableFields(CbrTransaction transaction) {
        LinkedHashMap<String, Object> snapshot = new LinkedHashMap<>();
        snapshot.put("reportType", normalizeText(transaction.getReportType()));
        snapshot.put("customerId", normalizeText(transaction.getCustomerId()));
        snapshot.put("paymentInstrument", normalizeText(transaction.getPaymentInstrument()));
        snapshot.put("specialMark", normalizeText(transaction.getSpecialMark()));
        snapshot.put("countryCode1", normalizeText(transaction.getCountryCode1()));
        snapshot.put("countryCode2", normalizeText(transaction.getCountryCode2()));
        snapshot.put("loanNumber", normalizeText(transaction.getLoanNumber()));
        snapshot.put("loanYear", normalizeText(transaction.getLoanYear()));
        snapshot.put("customerStp", normalizeText(transaction.getCustomerStp()));
        snapshot.put("drStatisticalCode", normalizeText(transaction.getDrStatisticalCode()));
        snapshot.put("crStatisticalCode", normalizeText(transaction.getCrStatisticalCode()));
        snapshot.put("regulatoryDetails", snapshotRegulatoryDetails(transaction));
        return snapshot;
    }

    private List<Map<String, Object>> snapshotRegulatoryDetails(CbrTransaction transaction) {
        if (transaction.getRegulatoryDetails() == null || transaction.getRegulatoryDetails().isEmpty()) {
            return List.of();
        }

        return transaction.getRegulatoryDetails().stream()
                .map(detail -> {
                    Map<String, Object> detailMap = new LinkedHashMap<>();
                    detailMap.put("id", detail.getId());
                    detailMap.put("splitStatCode", normalizeText(detail.getSplitStatCode()));
                    detailMap.put("splitAmount", normalizeAmount(detail.getSplitAmount()));
                    detailMap.put("invoiceNumber", normalizeText(detail.getInvoiceNumber()));
                    detailMap.put("invoiceYear", normalizeText(detail.getInvoiceYear()));
                    detailMap.put("splitAmountCurrency", normalizeText(detail.getSplitAmountCurrency()));
                    return detailMap;
                })
                .toList();
    }

    private Map<String, Object> calculateChanges(
            Map<String, Object> beforeSnapshot,
            Map<String, Object> afterSnapshot) {
        LinkedHashMap<String, Object> changes = new LinkedHashMap<>();
        Set<String> keys = new LinkedHashSet<>();
        keys.addAll(beforeSnapshot.keySet());
        keys.addAll(afterSnapshot.keySet());

        for (String key : keys) {
            Object before = beforeSnapshot.get(key);
            Object after = afterSnapshot.get(key);

            if ("regulatoryDetails".equals(key)) {
                appendRegulatoryDetailsChanges(changes, before, after);
                continue;
            }

            if (Objects.equals(before, after)) {
                continue;
            }
            changes.put(key + "_from", before);
            changes.put(key + "_to", after);
        }

        return changes;
    }

    private void appendRegulatoryDetailsChanges(
            LinkedHashMap<String, Object> changes,
            Object beforeValue,
            Object afterValue) {
        List<Map<String, Object>> beforeStats = asStatDetailsList(beforeValue);
        List<Map<String, Object>> afterStats = asStatDetailsList(afterValue);

        if (Objects.equals(beforeStats, afterStats)) {
            return;
        }

        Map<Long, Map<String, Object>> beforeById = toStatMapById(beforeStats);
        Map<Long, Map<String, Object>> afterById = toStatMapById(afterStats);

        int addCounter = 1;
        for (Map<String, Object> afterStat : afterStats) {
            Long statId = toLong(afterStat.get("id"));
            if (statId == null || !beforeById.containsKey(statId)) {
                changes.put("Dodavanje stat: " + addCounter, withoutId(afterStat));
                addCounter++;
            }
        }

        for (Map<String, Object> beforeStat : beforeStats) {
            Long statId = toLong(beforeStat.get("id"));
            if (statId == null) {
                continue;
            }

            Map<String, Object> afterStat = afterById.get(statId);
            if (afterStat == null) {
                changes.put("Brisanje stat " + statId, withoutId(beforeStat));
                continue;
            }

            Map<String, Object> beforeComparable = withoutId(beforeStat);
            Map<String, Object> afterComparable = withoutId(afterStat);
            if (!Objects.equals(beforeComparable, afterComparable)) {
                changes.put("Izmena stat " + statId + "_from", beforeComparable);
                changes.put("Izmena stat " + statId + "_to", afterComparable);
            }
        }
    }

    private List<Map<String, Object>> asStatDetailsList(Object value) {
        if (!(value instanceof List<?> rawList) || rawList.isEmpty()) {
            return List.of();
        }

        List<Map<String, Object>> result = new ArrayList<>();
        for (Object item : rawList) {
            if (item instanceof Map<?, ?> rawMap) {
                LinkedHashMap<String, Object> normalized = new LinkedHashMap<>();
                for (Map.Entry<?, ?> entry : rawMap.entrySet()) {
                    if (entry.getKey() != null) {
                        normalized.put(String.valueOf(entry.getKey()), entry.getValue());
                    }
                }
                result.add(normalized);
            }
        }
        return result;
    }

    private Map<Long, Map<String, Object>> toStatMapById(List<Map<String, Object>> stats) {
        LinkedHashMap<Long, Map<String, Object>> map = new LinkedHashMap<>();
        for (Map<String, Object> stat : stats) {
            Long id = toLong(stat.get("id"));
            if (id != null) {
                map.put(id, stat);
            }
        }
        return map;
    }

    private Map<String, Object> withoutId(Map<String, Object> value) {
        LinkedHashMap<String, Object> copy = new LinkedHashMap<>();
        value.forEach((key, fieldValue) -> {
            if (!"id".equals(key)) {
                copy.put(key, fieldValue);
            }
        });
        return copy;
    }

    private Long toLong(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Number numberValue) {
            return numberValue.longValue();
        }
        try {
            return Long.valueOf(String.valueOf(value));
        } catch (NumberFormatException ex) {
            return null;
        }
    }

    private boolean isEmptyRegulatoryDetail(ManualEntryDetailsUpdateRequest.RegulatoryDetailItem detail) {
        return detail.getId() == null
                && isBlank(detail.getSplitStatCode())
                && isBlank(detail.getSplitAmount())
                && isBlank(detail.getInvoiceNumber())
                && isBlank(detail.getInvoiceYear())
                && isBlank(detail.getSplitAmountCurrency());
    }

    private BigDecimal parseBigDecimal(String rawValue, String fieldName) {
        String normalized = normalizeText(rawValue);
        if (normalized == null) {
            return null;
        }

        String decimalValue = normalized.replace(",", ".");
        try {
            return new BigDecimal(decimalValue);
        } catch (NumberFormatException ex) {
            throw new ResponseStatusException(
                    HttpStatus.BAD_REQUEST,
                    "Invalid decimal value for " + fieldName + ": " + rawValue);
        }
    }

    private String normalizeAmount(BigDecimal value) {
        if (value == null) {
            return null;
        }
        return value.stripTrailingZeros().toPlainString();
    }

    private String normalizeText(String value) {
        if (value == null) {
            return null;
        }
        String trimmed = value.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private void markOrderSubmittedBy(CbrTransaction transaction, String currentUsername) {
        if (transaction == null || isBlank(currentUsername)) {
            return;
        }
        transaction.setOrderSubmittedBy(currentUsername.trim());
    }

    private String resolveCurrentUsername() {
        try {
            String username = currentUserService.getUsername();
            if (!isBlank(username)) {
                return username.trim();
            }
        } catch (Exception ignored) {
            // Fallback is used when request is executed outside user-authenticated context.
        }
        return "SYSTEM";
    }

    private List<String> collectValidationFailures(List<ValidationApplyResult> validationResults) {
        if (validationResults == null || validationResults.isEmpty()) {
            return List.of();
        }

        List<String> failures = new ArrayList<>();
        boolean hasMatchedMatrixRule = false;

        for (ValidationApplyResult result : validationResults) {
            if (result == null || result.getFailedConditions() == null || result.getFailedConditions().isEmpty()) {
                if (result != null
                        && !isPostMatrixValidationNo(result.getValidationNo())
                        && result.isMatched()) {
                    hasMatchedMatrixRule = true;
                }
                continue;
            }

            if (!isPostMatrixValidationNo(result.getValidationNo())) {
                if (result.isMatched()) {
                    hasMatchedMatrixRule = true;
                }
                continue;
            }

            String validationNo = result.getValidationNo() == null
                    ? "N/A"
                    : result.getValidationNo().stripTrailingZeros().toPlainString();

            for (String failedCondition : result.getFailedConditions()) {
                if (isBlank(failedCondition)) {
                    continue;
                }
                failures.add("Validation " + validationNo + ": " + failedCondition.trim());
            }
        }

        if (!hasMatchedMatrixRule) {
            failures.add(0, VALIDATION_SCHEMA_NOT_SATISFIED_MESSAGE);
        }

        return failures;
    }

    private boolean isPostMatrixValidationNo(BigDecimal validationNo) {
        if (validationNo == null) {
            return false;
        }

        BigDecimal normalized = validationNo.stripTrailingZeros();
        if (normalized.scale() > 0) {
            return false;
        }

        return normalized.compareTo(BigDecimal.ONE) >= 0
                && normalized.compareTo(BigDecimal.valueOf(15L)) <= 0;
    }
