        String actionSplitAmount = rule.getActionSplitAmount();
        String actionInvoiceNumber = rule.getActionInvoiceNumber();
        String actionInvoiceYear = rule.getActionInvoiceYear();

        boolean hasAnySplitAction = !isBlank(actionSplitStatCode)
                || !isBlank(actionSplitAmount)
                || !isBlank(actionInvoiceNumber)
                || !isBlank(actionInvoiceYear);
        if (!hasAnySplitAction) {
            return false;
        }

        if (entity.getRegulatoryDetails() == null) {
            entity.setRegulatoryDetails(new ArrayList<>());
        }

        if (entity.getRegulatoryDetails().isEmpty()) {
            if (isExplicitNull(actionSplitStatCode)
                    || isExplicitNull(actionSplitAmount)
                    || isExplicitNull(actionInvoiceNumber)
                    || isExplicitNull(actionInvoiceYear)) {
                return false;
            }
            CbrTransactionStat stat = new CbrTransactionStat();
            stat.setTransaction(entity);
            entity.getRegulatoryDetails().add(stat);
        }

        boolean changed = false;
        for (CbrTransactionStat stat : entity.getRegulatoryDetails()) {
            changed |= applyActionValue(
                    actionSplitStatCode, stat.getSplitStatCode(), stat::setSplitStatCode,
                    entity, "SPLIT_STAT_CODE", true).applied;
            changed |= applyActionBigDecimalValue(
