                results.add(globalValidationFailure("4", RULE4_SPLIT_ERROR_MESSAGE));
            }
            if (!isRule5SplitStatCodeValid(txn)) {
                results.add(globalValidationFailure("5", RULE5_SPLIT_ERROR_MESSAGE));
            }
        }
        if ("66".equals(reportType)) {
            if (!isRule6DrCrStatCodeValid(txn)) {
                results.add(globalValidationFailure("6", RULE6_DR_CR_ERROR_MESSAGE));
            }
        }
        if ("77".equals(reportType)) {
