    private ValidationApplyResult globalValidationFailure(String validationNo, String message) {
        java.math.BigDecimal no = null;
        if (!isBlank(validationNo)) {
            try {
                no = new java.math.BigDecimal(validationNo.trim());
            } catch (NumberFormatException ignored) {
                // keep null if unexpected value appears
            }
        }
        return ValidationApplyResult.builder()
                .validationNo(no)
                .matched(false)
                .applied(false)
                .failedConditions(List.of(message))
                .build();
    }

