        try {
            return transactionRepository.findWithRegulatoryDetailsByRequestId(requestId)
                    .map(txn -> {
                        List<String> failureCodes = evaluateStpManualFailures(txn);
                        List<StpFailure> failures = failureCodes.stream()
                                .map(code -> StpFailure.builder()
