                                        .message(stpFailureMessage(code))
                                        .build())
                                .toList();
                        boolean manualRequired = !failures.isEmpty();
                        StpManualCheckResponse response = StpManualCheckResponse.builder()
                                .manualRequired(manualRequired)
                                .failures(failures)
                                .build();
                        boolean logged = saveStpValidationLog(requestId, response);
                        if (logged) {
                            updateStpStatuses(requestId, response);
                        }
                        return response;
                    });
        } catch (Exception ex) {
            stageTransitionService.transitionErrorByRequestId(
                    requestId, "Greska pri STP validaciji", ex.getMessage());
            throw ex;
        }
    }

    private boolean matchesMessageTypeAndDirection(CbrTransaction txn, CbrValidationMatrix rule) {
        if (txn == null || rule == null) {
            return false;
        }
        String messageType = valueOf(txn.getMessageType());
        String direction = valueOf(txn.getDirection());
        return matches(rule.getCondMessageType(), messageType)
                && matches(rule.getCondDirection(), direction);
    }

    private void saveValidationLog(Long requestId, List<ValidationApplyResult> results) {
        if (requestId == null) {
            return;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
        Long maxRunNo = validationLogRepository.findMaxRunNoByRequestId(requestId);
        long nextRunNo = maxRunNo == null ? 1L : maxRunNo + 1L;
        String json;
        try {
            json = objectMapper.writeValueAsString(results);
        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
            throw new IllegalStateException("Failed to serialize validation results", ex);
        }
        boolean anyApplied = results.stream().anyMatch(ValidationApplyResult::isApplied);
        boolean hasPostMatrixValidationFailures = hasBlockingPostMatrixValidationFailure(results);
        String success = (anyApplied && !hasPostMatrixValidationFailures) ? "YES" : "NO";
        CbrValidationMatrixLog logEntry = CbrValidationMatrixLog.builder()
                .request(request)
                .runNo(nextRunNo)
                .validationResultJson(json)
                .success(success)
                .build();
        validationLogRepository.save(logEntry);
    }

    private boolean saveStpValidationLog(Long requestId, StpManualCheckResponse response) {
        if (requestId == null || response == null) {
            return false;
        }
        CbrTransactionRequest request = requestRepository.findById(requestId)
                .orElseThrow(() -> new IllegalArgumentException("Request not found: " + requestId));
        String json;
        try {
            json = objectMapper.writeValueAsString(response);
        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
            throw new IllegalStateException("Failed to serialize STP validation response", ex);
        }
        String success = response.isManualRequired() ? "NO" : "YES";
        CbrStpValidationLog logEntry = CbrStpValidationLog.builder()
                .request(request)
                .stpResultJson(json)
                .success(success)
                .build();
        stpValidationLogRepository.save(logEntry);
        return true;
    }

    private void updateStpStatuses(Long requestId, StpManualCheckResponse response) {
        if (requestId == null || response == null) {
            return;
        }
        String customerStp = response.isManualRequired() ? CUSTOMER_STP_MANUAL : CUSTOMER_STP_AUTO;
        transactionRepository.findWithRegulatoryDetailsByRequestId(requestId).ifPresent(txn -> {
            String currentValue = normalize(txn.getCustomerStp());
            if (!Objects.equals(currentValue, customerStp)) {
                txn.setCustomerStp(customerStp);
                transactionRepository.save(txn);
                LOG.info("Updated CUSTOMER_STP={} for requestId={} txnId={}", customerStp, requestId, txn.getId());
            }
        });

        String status = response.isManualRequired() ? "S7" : "S9";
        stageTransitionService.transitionByRequestId(requestId, status, "STP status update");
    }

    private void updateValidationStatuses(Long requestId, List<ValidationApplyResult> results) {
