@RestControllerAdvice
public class ExceptionHandlerController extends ResponseEntityExceptionHandler {

     private static final Logger log = LoggerFactory.getLogger(ExceptionHandlerController.class);
     private static final String VALIDATION_FAILED_PREFIX = "VALIDATION_FAILED::";
     private static final String VALIDATION_FAILED_SEPARATOR = "\\|\\|";
     private static final String TX_LOCKED_PREFIX = "TX_LOCKED::";
	
	 private Map<String, Object> body(HttpStatus status, String message, String path) {
	        return Map.of(
	            "timestamp", Instant.now().toString(),
	            "status", status.value(),
	            "error", status.getReasonPhrase(),
	            "message", message,
	            "path", path
	        );
	    }

	 @ExceptionHandler(CurrentUserException.class)
	 public ResponseEntity<Map<String, Object>> handleCurrentUserNotAuthenticated(CurrentUserException ex, HttpServletRequest request) {
		 log.warn("CurrentUserException: {}", ex.getMessage());
		 return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(body(HttpStatus.UNAUTHORIZED, ex.getMessage(), request.getRequestURI()));
	    }

     @ExceptionHandler(ResponseStatusException.class)
     public ResponseEntity<Map<String, Object>> handleResponseStatusException(
             ResponseStatusException ex,
             HttpServletRequest request) {
         HttpStatusCode statusCode = ex.getStatusCode();
         HttpStatus httpStatus = statusCode instanceof HttpStatus resolved ? resolved : HttpStatus.INTERNAL_SERVER_ERROR;
         String reason = ex.getReason() == null ? httpStatus.getReasonPhrase() : ex.getReason();

         LinkedHashMap<String, Object> responseBody = new LinkedHashMap<>();
         responseBody.put("timestamp", Instant.now().toString());
         responseBody.put("status", statusCode.value());
         responseBody.put("error", httpStatus.getReasonPhrase());
         responseBody.put("path", request.getRequestURI());

         if (reason.startsWith(VALIDATION_FAILED_PREFIX)) {
             String rawErrors = reason.substring(VALIDATION_FAILED_PREFIX.length());
             List<String> validationErrors = Arrays.stream(rawErrors.split(VALIDATION_FAILED_SEPARATOR))
                     .map(String::trim)
                     .filter(item -> !item.isEmpty())
                     .toList();
             responseBody.put("message", "VALIDATION_FAILED");
             responseBody.put("validationErrors", validationErrors);
         } else if (reason.startsWith(TX_LOCKED_PREFIX)) {
             String lockOwner = reason.substring(TX_LOCKED_PREFIX.length()).trim();
             responseBody.put("message", "TX_LOCKED");
             responseBody.put("code", "TX_LOCKED");
             responseBody.put("lockedBy", lockOwner.isEmpty() ? "UNKNOWN" : lockOwner);
         } else {
             responseBody.put("message", reason);
         }

         return ResponseEntity.status(statusCode).body(responseBody);
     }

}

